function mzRng(seed){
  var s=(seed>>>0)||1;
  return function(){
    s|=0; s=(s+0x6D2B79F5)|0;
    var t=Math.imul(s^(s>>>15), 1|s);
    t=(t+Math.imul(t^(t>>>7), 61|t))^t;
    return ((t^(t>>>14))>>>0)/4294967296;
  };
}
function mzGen(w, h, seed){
  if(!Number.isInteger(w)||!Number.isInteger(h)||w<3||h<3||w>60||h>60)
    return { value:null, error:'宽高须为 3-60 的整数' };
  var rnd=mzRng(seed===undefined?42:seed);
  var cells=[], y, x;
  for(y=0;y<h;y++){ var r=[]; for(x=0;x<w;x++) r.push({ n:1,s:1,e:1,w:1,seen:0 }); cells.push(r); }
  var stack=[[0,0]]; cells[0][0].seen=1; var visited=1;
  var D=[['n',0,-1,'s'],['s',0,1,'n'],['e',1,0,'w'],['w',-1,0,'e']];
  while(stack.length){
    var cur=stack[stack.length-1], cx=cur[0], cy=cur[1];
    var opts=[];
    for(var d=0;d<4;d++){
      var nx=cx+D[d][1], ny=cy+D[d][2];
      if(nx>=0&&ny>=0&&nx<w&&ny<h&&!cells[ny][nx].seen) opts.push(d);
    }
    if(!opts.length){ stack.pop(); continue; }
    var pick=D[opts[Math.floor(rnd()*opts.length)]];
    var tx=cx+pick[1], ty=cy+pick[2];
    cells[cy][cx][pick[0]]=0;
    cells[ty][tx][pick[3]]=0;
    cells[ty][tx].seen=1; visited++;
    stack.push([tx,ty]);
  }
  for(y=0;y<h;y++) for(x=0;x<w;x++) delete cells[y][x].seen;
  return { value:{ width:w, height:h, cells:cells, visited:visited }, error:null };
}
function mzSolve(maze, sx, sy, ex, ey){
  var w=maze.width, h=maze.height, c=maze.cells;
  sx=sx||0; sy=sy||0;
  if(ex===undefined) ex=w-1;
  if(ey===undefined) ey=h-1;
  if(sx<0||sy<0||sx>=w||sy>=h||ex<0||ey<0||ex>=w||ey>=h)
    return { value:null, error:'起终点越界' };
  var prev={}, q=[[sx,sy]], seen={}; seen[sx+','+sy]=1; var expanded=0;
  var D=[['n',0,-1],['s',0,1],['e',1,0],['w',-1,0]];
  while(q.length){
    var cur=q.shift(), x=cur[0], y=cur[1]; expanded++;
    if(x===ex&&y===ey){
      var path=[], k=ex+','+ey;
      while(k){ var p=k.split(','); path.unshift([+p[0],+p[1]]); k=prev[k]; }
      return { value:{ path:path, length:path.length, expanded:expanded }, error:null };
    }
    for(var d=0;d<4;d++){
      if(c[y][x][D[d][0]]) continue;
      var nx=x+D[d][1], ny=y+D[d][2], key=nx+','+ny;
      if(seen[key]) continue;
      seen[key]=1; prev[key]=x+','+y; q.push([nx,ny]);
    }
  }
  return { value:null, error:'不可达（迷宫数据损坏？）' };
}
function mzSvg(maze, path){
  var w=maze.width, h=maze.height, C=Math.max(10, Math.min(26, Math.floor(520/w)));
  var W=w*C+4, H=h*C+4, c=maze.cells;
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  if(path && path.length){
    var pts=path.map(function(p){ return (p[0]*C+2+C/2)+','+(p[1]*C+2+C/2); }).join(' ');
    s+='<polyline points="'+pts+'" fill="none" stroke="#10B981" stroke-width="'+Math.max(2,C/4)+'" stroke-linejoin="round" stroke-linecap="round" opacity="0.9"/>';
  }
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var px=x*C+2, py=y*C+2, cell=c[y][x];
    if(cell.n) s+='<line x1="'+px+'" y1="'+py+'" x2="'+(px+C)+'" y2="'+py+'" stroke="#5E6AD2" stroke-width="1.5"/>';
    if(cell.w) s+='<line x1="'+px+'" y1="'+py+'" x2="'+px+'" y2="'+(py+C)+'" stroke="#5E6AD2" stroke-width="1.5"/>';
    if(y===h-1&&cell.s) s+='<line x1="'+px+'" y1="'+(py+C)+'" x2="'+(px+C)+'" y2="'+(py+C)+'" stroke="#5E6AD2" stroke-width="1.5"/>';
    if(x===w-1&&cell.e) s+='<line x1="'+(px+C)+'" y1="'+py+'" x2="'+(px+C)+'" y2="'+(py+C)+'" stroke="#5E6AD2" stroke-width="1.5"/>';
  }
  s+='<circle cx="'+(2+C/2)+'" cy="'+(2+C/2)+'" r="'+(C/5)+'" fill="#22D3EE"/>';
  s+='<circle cx="'+((w-1)*C+2+C/2)+'" cy="'+((h-1)*C+2+C/2)+'" r="'+(C/5)+'" fill="#F5A623"/>';
  s+='</svg>';
  return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { mzRng:mzRng, mzGen:mzGen, mzSolve:mzSolve, mzSvg:mzSvg };
}
if (typeof window !== 'undefined') {
  window.MazeForgePure = { mzRng:mzRng, mzGen:mzGen, mzSolve:mzSolve, mzSvg:mzSvg };
}
